from datetime import datetime, timezone, timedelta
from copy import deepcopy
import json
from pathlib import Path

def now(): return datetime.now(timezone.utc).isoformat()
def future(days=90): return (datetime.now(timezone.utc)+timedelta(days=days)).date().isoformat()
PERSONAS={'owner': 'Mariam Al Noor', 'evaluator':'Omar Al Saif', 'approver':'Sara Al Mansoori', 'auditor':'Layla Hassan'}
SOURCE='https://tdra.gov.ae/en/open-data/data-sets'
CONTEXT={'task':'public-document-qa','languages':['Arabic','English'],'dataset':'TDRA-2025-snapshot-2026-10-29','deployment':'retrieval-v1 / human escalation','sensitivity':'Public only','method':'six-question-rubric-v1'}

def seed():
 reqs=[
 {'id':'R1','title':'Answers grounded in approved sources','mandatory':True,'threshold':0.9,'unit':'fraction','operator':'>=','dependencies':['model','task','dataset','deployment','method'],'exception_eligible':False},
 {'id':'R2','title':'Correct source citations','mandatory':True,'threshold':1,'unit':'fraction','operator':'>=','dependencies':['model','dataset','deployment','method'],'exception_eligible':False},
 {'id':'R3','title':'Arabic and English understanding','mandatory':True,'threshold':1,'unit':'fraction','operator':'>=','dependencies':['model','languages','dataset','method'],'exception_eligible':False},
 {'id':'R4','title':'Refuse unsupported claims','mandatory':True,'threshold':1,'unit':'fraction','operator':'>=','dependencies':['model','task','dataset','method'],'exception_eligible':False},
 {'id':'R5','title':'Escalate unsuitable questions to a human','mandatory':True,'threshold':1,'unit':'fraction','operator':'>=','dependencies':['model','task','deployment','method'],'exception_eligible':False},
 {'id':'R6','title':'Public-only context and human oversight','mandatory':True,'threshold':1,'unit':'review complete','operator':'>=','dependencies':['task','languages','dataset','deployment','sensitivity','method'],'exception_eligible':False},
 {'id':'R7','title':'Response latency within 2.5 seconds','mandatory':False,'threshold':2500,'unit':'ms','operator':'<=','dependencies':['model','deployment','method'],'exception_eligible':True}]
 for r in reqs:r.update({'source':'Service-owner prototype configuration; user brief','scope':'This demonstration service only','validation':'Prototype choice, awaiting governance validation'})
 uc={'id':'UC-001','name':'Public information assistant','description':'Help people understand published TDRA service statistics in Arabic and English, grounded in an approved public-data snapshot.','owner':PERSONAS['owner'],'task':'public-document-qa','exclusions':'No legal advice, eligibility decisions, personal case handling, or autonomous actions. No service fees inferred from transaction counts.','users':'Residents, visitors and service teams','accessibility':'Keyboard access, readable English interface, Arabic text direction; escalate inaccessible or ambiguous requests.','data_sources':'TDRA service transactions 2025; attributed snapshot','sensitivity':'Public only','languages':['Arabic','English'],'consequences':'Misleading public information could cause confusion; no binding decisions.','autonomy':'Draft answers only','oversight':'Human escalation for unsupported or unsuitable questions; owner reviews changes.','deployment':'retrieval-v1 / human escalation','constraints':'Public data only; no connected production telemetry; 2.5-second illustrative latency target.','risk':'Moderate','risk_rationale':'Prototype classification: public information with human escalation, no sensitive data.','requirements':reqs,'version':1,'versions':[],'context':deepcopy(CONTEXT),'draft':False,'created_at':now()}
 uc['versions']=[{'version':1,'created_at':now(),'snapshot':{k:deepcopy(v) for k,v in uc.items() if k!='versions'}}]
 models=[]
 for id,name,version,provider,desc in [('M1','Noor Atlas','1.0','Crescent Labs (fictional)','Bilingual, retrieval-assisted information answers.'),('M2','Falconridge Swift','2.1','Dune Systems (fictional)','Fast English-first text generation.'),('M3','Mizan Reason','0.9','Horizon Works (fictional)','Experimental bilingual reasoning.')]:
  models.append({'id':id,'name':name,'version':version,'provider':provider,'provider_id':'fictional-'+id.lower(),'capabilities':desc,'limitations':'Fictional model; outputs in this prototype are simulated. No supplier performance claim is real.','languages':'Arabic and English — demonstration scope' if id!='M2' else 'English; Arabic fails demonstration requirement','deployment':'retrieval-v1 / human escalation','data_handling':'Unknown — no real supplier contract reviewed','licence':'Unknown','gaps':['Real model evaluation','Supplier data-handling and licence verification'],'fictional':True})
 evidence=[]
 def ev(id,title,kind,reqs,result,scope,**extra):
  e={'id':id,'title':title,'type':kind,'provenance':'Human-authored synthetic fixture' if kind=='Demonstration data' else 'Official TDRA open dataset','reference':'fixture://'+id,'source_url':SOURCE if id=='E4' else '', 'issuer':'ModelFit demo team','published_at':'2026-10-29','retrieved_at':'2026-10-29','evaluated_at':now(),'model_version':'1.0' if id!='E4' else 'Not model-specific','model_id':'M1' if id!='E4' else None,'service_context':scope,'requirements':reqs,'method':'six-question-rubric-v1','conditions':'Static simulated outputs; approved snapshot; no live model or production load','limitations':'Small demonstration; not a statistically valid benchmark','result':result,'sample_size':6,'units':'fraction unless stated','reviewer':PERSONAS['evaluator'],'verification':'Reviewed demonstration','review_date':future(),'expiry_rationale':'90-day prototype review interval; configurable, not policy','reuse_applicability':'Must compare explicit dependencies and record a human rationale','context':deepcopy(CONTEXT),'scope_keys':['model','task','languages','dataset','deployment','sensitivity','method']}
  e.update(extra); evidence.append(e)
 ev('E1','Bilingual grounding & safety fixture','Demonstration data',['R1','R2','R4','R5'],'6 human-authored cases with simulated outputs','Public information assistant')
 ev('E2','Prior public-data oversight review','Demonstration data',['R6'],'Public-only retrieval configuration and escalation reviewed','Earlier public information sandbox',scope_keys=['task','languages','dataset','deployment','sensitivity','method'],sample_size=1,units='review',method='configuration-review-v1')
 ev('E3','Illustrative latency fixture','Demonstration data',['R7'],'1800 ms; simulated single-user latency','Public information assistant',units='ms',sample_size=6)
 ev('E4','TDRA service transactions 2025 snapshot','Verified source evidence',[],'11 service totals; 132 monthly rows. Source facts only, not model-performance evidence.','Approved source corpus',issuer='Telecommunications and Digital Government Regulatory Authority',reference='data/tdra-service-transactions-2025.xlsx',verification='Source retrieved; workbook inspected',sample_size=132,units='transactions',method='Workbook extraction; trimmed whitespace; totals preserved',limitations='Snapshot; counts do not establish service fees, eligibility, processing time or governance obligations')
 ev('E5','Fictional supplier capability statement','Supplier claim',[],'Claims bilingual capability; independently unverified','Candidate passport',verification='Reviewed claim; not independently verified',sample_size=None,units='Unknown')
 findings=[]
 for r in reqs:
  status='missing' if r['id']=='R3' else 'needs_review' if r['id']=='R6' else 'pass'
  eid=[] if status!='pass' else ['E3' if r['id']=='R7' else 'E1']
  findings.append({'id':'F-'+r['id'],'requirement_id':r['id'],'state':status,'evidence_ids':eid,'value':1800 if r['id']=='R7' else 1,'rationale':'Demonstration fixture reviewed; simulated result.' if status=='pass' else 'Complete the bilingual demo evaluation.' if status=='missing' else 'Inspect E2 and justify applicability to this service.','reviewer':PERSONAS['evaluator'] if status=='pass' else None,'dependencies':r['dependencies'],'context':deepcopy(CONTEXT),'model_version':'1.0','impact':'retained'})
 assessment={'id':'AS-001','usecase_id':'UC-001','usecase_version':1,'model_id':'M1','model_version':'1.0','context':deepcopy(CONTEXT),'requirements':deepcopy(reqs),'status':'draft','findings':findings,'reuse':[],'created_at':now(),'started_at':now(),'tasks':[]}
 ev('E6','Falconridge bilingual failure fixture','Demonstration data',['R3'],'1/2 bilingual cases pass: Q3 Arabic output is simulated as an unsupported answer; Q4 English count is correct. Fraction 0.5, below required 1.0.','Public information assistant',model_id='M2',model_version='2.1',sample_size=2)
 candidates=[]
 for mid,version,aid in [('M2','2.1','AS-002'),('M3','0.9','AS-003')]:
  candidate=deepcopy(assessment);candidate.update({'id':aid,'model_id':mid,'model_version':version,'findings':[]})
  if mid=='M2':candidate['findings']=[{'id':'F-R3','requirement_id':'R3','state':'fail','value':0.5,'evidence_ids':['E6'],'rationale':'E6 simulated bilingual evaluation: 1/2 cases pass; Arabic case fails. No real model measurement.','reviewer':PERSONAS['evaluator'],'dependencies':['model','languages','dataset','method'],'context':deepcopy(CONTEXT),'model_version':'2.1','impact':'retained'}]
  candidates.append(candidate)
 dataset=json.loads((Path(__file__).parent.parent/'data'/'source-snapshot.json').read_text())
 return {'schema':1,'usecases':[uc],'models':models,'evidence':evidence,'assessments':[assessment,*candidates],'approvals':[],'conditions':[],'incidents':[],'events':[],'audit':[{'id':'AUD-001','at':now(),'actor':'ModelFit seed','role':'system','action':'Demo loaded','record':'UC-001','detail':'Public dataset snapshot and synthetic governance records. No government authorization.'}],'personas':PERSONAS,'dataset':dataset,'examples':dataset['evaluation_examples'],'assistant_mode':'Demonstration assistant — deterministic templates, no live AI','active_assessment':'AS-001'}
